// devices.platformSites.read — the projects the device platform job works on. Generated by `pnpm gen:query`;
// acceptance cases added.
import { afterAll, beforeAll, describe, expect, inject, it } from 'vitest';
import { aStaffActor, createTestDatabase, runAsOwner, type TestDatabase } from '@ocs/testing';
import { Forbidden, grantOf, openTestKernel, systemActor, type TestKernel } from '../../kernel/index.ts';
import { createClient, createSite } from '../../org/index.ts';
import { platformSites } from '../queries/platform-sites.ts';

const job = systemActor('device-platform');
let testDb: TestDatabase;
let t: TestKernel;
const ids: string[] = [];

beforeAll(async () => {
  testDb = await createTestDatabase(inject('postgresUrl'));
  t = await openTestKernel(testDb.url);
  const setup = aStaffActor({ roles: ['director'] });
  t.grant(setup, createClient.permission, createSite.permission);
  t.grant(job, platformSites.permission);
  const a = await t.kernel.execute(createClient, setup, { shortCode: 'CLIENTA', name: 'Client A' }, 'test');
  const place = { countryCode: 'ES', cityCode: 'MAD', cityName: 'Madrid', name: 'Mall', standard: 'L' };
  for (let n = 0; n < 4; n += 1) {
    ids.push((await t.kernel.execute(createSite, setup, { clientId: a.id, ...place }, 'test')).id);
  }
  const set = (sql: string, id: string | undefined) => runAsOwner(testDb.url, sql, [id]);
  await set(`UPDATE site SET platform_ref = 'mall-a', device_alerts_enabled = true WHERE id = $1`, ids[0]);
  await set(`UPDATE site SET platform_ref = 'mall-b' WHERE id = $1`, ids[1]);
  await set(`UPDATE site SET platform_ref = 'mall-c', archived_at = now() WHERE id = $1`, ids[2]);
});

afterAll(async () => {
  await t.close();
  await testDb.drop();
});

describe('devices.platformSites.read', () => {
  it('is for the system role only', async () => {
    expect(grantOf(platformSites.permission)?.roles).toEqual(['system']);
    await expect(t.kernel.read(platformSites, aStaffActor(), {})).rejects.toBeInstanceOf(Forbidden);
  });

  it('lists active projects linked to a mall, with their alerts checkbox', async () => {
    const sites = await t.kernel.read(platformSites, job, {});
    expect(sites.map((s) => [s.siteId, s.platformRef, s.alertsEnabled])).toEqual([
      [ids[0], 'mall-a', true],
      [ids[1], 'mall-b', false],
    ]);
  });
});
